mapper.select:
select cct.code_type as code_type , cct.code_type_nm as code_type_nm , cct.code_type_nm_s as code_type_nm_s , to_char(cct.start_date, 'yyyy-mm-dd') as start_date , to_char(cct.end_date, 'yyyy-mm-dd') as end_date , cct.create_type_cd as create_type_cd , cct.remark as remark , cct.create_date as create_date , cct.create_by as create_by , cct.update_date as update_date , cct.update_by as update_by from com_code_type cct where 1=1
and cct.code_type = #{code_type}
and cct.code_type_nm like #{code_type_name} || '%'

select cc.code_type as code_type ,cc.code as code ,cc.code_nm as code_nm ,cc.code_nm_s as code_nm_s ,to_char(cc.start_date, 'yyyy-mm-dd') as start_date ,to_char(cc.end_date, 'yyyy-mm-dd') as end_date ,cc.sort_order as sort_order ,cc.attr_chr1 as attr_chr1 ,cc.attr_chr2 as attr_chr2 ,cc.attr_chr3 as attr_chr3 ,cc.attr_chr4 as attr_chr4 ,cc.attr_chr5 as attr_chr5 ,cc.attr_num1 as attr_num1 ,cc.attr_num2 as attr_num2 ,cc.attr_num3 as attr_num3 ,cc.attr_num4 as attr_num4 ,cc.attr_num5 as attr_num5 ,cc.attr_date1 as attr_date1 ,cc.attr_date2 as attr_date2 ,cc.attr_date3 as attr_date3 ,cc.attr_date4 as attr_date4 ,cc.attr_date5 as attr_date5 ,cc.remark as remark ,cc.create_date as create_date ,cc.create_by as create_by ,cc.update_date as update_date ,cc.update_by as update_by from com_code cc where 1=1
and cc.code_type = #{code_type}
and cc.code = #{code}
and cc.code_nm like #{code_nm} || '%'
order by cc.code_type ,cc.code
